def _floor_to_minute(timestamp: float) -> float:
    return (timestamp // 60) * 60


def _insert(title: str, due_at: float) -> Task:
    tasks = load_all()
    task = Task(id=next_id(tasks), title=title, due_at=due_at)
    tasks.append(task)
    save_all(tasks)
    return task


def create_task(title: str, due_in_seconds: float) -> Task:
    """Create a task due `due_in_seconds` seconds from now."""
    return _insert(title, time.time() + due_in_seconds)


def quick_add(title: str) -> Task:
    """Create a task due 24 hours from now, rounded down to a whole minute."""
    return _insert(title, _floor_to_minute(time.time() + 24 * 3600))


def postpone_task(task_id: int, hours: int) -> Task | None:
    """Push a task's due_at back by `hours` hours, rounded down to a whole minute.

    Returns the updated task, or None if there is no task with that id.
    """
    tasks = load_all()
    task = next((t for t in tasks if t.id == task_id), None)
    if task is None:
        return None
    task.due_at = _floor_to_minute(task.due_at + hours * 3600)
    save_all(tasks)
    return task

